<?php
declare(strict_types=1);
require __DIR__.'/hybrid-isolation.php';
use App\Services\{HybridDatabaseScope,HybridInvoiceRequest as J};
$m=HybridIsolationHarness::manifest($argv[1]??'');$pdo=HybridIsolationHarness::connection($m);HybridDatabaseScope::verify($pdo,$m);
$config=require APP_ROOT.'/config/hybrid-promotions.php';foreach(['enabled','sale_posting','return_posting','custody']as$key)if($config[$key]!==false)throw new RuntimeException('Source must remain disabled.');if($config['financial_posting_hold']!==true||$config['databases']!==[]||$config['bindings']!==[])throw new RuntimeException('Source safety defaults changed.');
$checksums=[];foreach(['025_hybrid_invoice_snapshots.sql','026_hybrid_linked_returns.sql','027_hybrid_custody_dispositions.sql']as$file){$q=$pdo->prepare('SELECT checksum,status FROM schema_migrations WHERE version=?');$q->execute([$file]);$row=$q->fetch();$hash=hash_file('sha256',APP_ROOT.'/database/migrations/'.$file);if(!$row||$row['status']!=='applied'||!hash_equals($row['checksum'],$hash))throw new RuntimeException('Migration checksum mismatch.');$checksums[$file]=$hash;}
$f=json_decode(file_get_contents($m['directory'].'/fixtures-stage3.json'),true,512,JSON_THROW_ON_ERROR);
