$proof=['database'=>$m['database'],'port'=>$m['port'],'datadir'=>$m['datadir'],'controls'=>$after,'source_disabled'=>true,'source_posting_hold'=>true,'migration_checksums'=>$checksums];file_put_contents($m['directory'].'/stage4-closeout.json',json_encode($proof,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo "Stage 4 closeout: verified physical test scope, all disposable controls disabled, source hold and disabled configuration preserved, migration checksums matched.\n";
